// JATS (Journal Article Tag Suite, NISO Z39.96) XML for one article: the
// format PubMed Central, DOAJ, Scopus, EBSCO and most aggregators accept.
// The article body is converted from the site's HTML (which is generated by
// src/lib/importer/markup.ts, so it is regular and well-formed).
import type { Article, Issue } from "@/db/schema";
import { plain } from "@/lib/importer/markup";
import type { JournalConfig } from "@/lib/journal-config";
import {
  absUrl, articleUrl, authorRecords, doiIn, jatsType, licenceInfo, monthNum, pdfUrl, pmidIn, xml,
} from "./common";

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", ndash: "–", mdash: "—", hellip: "…", middot: "·", deg: "°", plusmn: "±", micro: "µ", times: "×", le: "≤", ge: "≥", rsquo: "’", lsquo: "‘", rdquo: "”", ldquo: "“" };
const decode = (s: string) =>
  s.replace(/&(#x[0-9a-f]+|#\d+|\w+);/gi, (m, e: string) => {
    if (e[0] === "#") { const n = e[1].toLowerCase() === "x" ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10); return Number.isFinite(n) ? String.fromCodePoint(n) : m; }
    return ENTITIES[e.toLowerCase()] ?? m;
  });

const attrsOf = (s: string) => {
  const out: Record<string, string> = {};
  for (const m of s.matchAll(/([^\s=]+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g)) out[m[1].toLowerCase()] = decode(m[2] ?? m[3] ?? m[4] ?? "");
  return out;
};

const BLOCK_PARENTS = new Set(["body", "sec", "boxed-text", "list", "table-wrap", "fig", "table", "thead", "tbody", "tr", "notes", "caption-wrap"]);

/** Converts article HTML to JATS body content (sections, paragraphs, lists, tables, figures, boxes). */
export function htmlToJats(html: string, cfg: JournalConfig, idPrefix = "") {
  const out: string[] = [];
  // Each entry: the JATS closing markup to emit when the matching HTML element closes.
  type Frame = { tag: string; close: string; jats: string };
  const stack: Frame[] = [];
  const secs: number[] = []; // depths of open <sec>
  let figN = 0, tabN = 0, boxN = 0, pendingGraphic: string[] | null = null;
  const top = () => stack[stack.length - 1];
  const jatsParent = () => { for (let i = stack.length - 1; i >= 0; i--) if (stack[i].jats) return stack[i].jats; return secs.length ? "sec" : "body"; };
  const inside = (tag: string) => stack.some((f) => f.tag === tag);
  const closeSecs = (depth: number) => { while (secs.length && secs[secs.length - 1] >= depth) { out.push("</sec>"); secs.pop(); } };

  const re = /<!--[\s\S]*?-->|<(\/?)([a-zA-Z][a-zA-Z0-9]*)([^>]*?)(\/?)>|([^<]+)|</g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html))) {
    if (m[0].startsWith("<!--")) continue;
    if (m[5] !== undefined || m[0] === "<") {
      const text = decode(m[5] ?? "<");
      const parent = jatsParent();
      if (BLOCK_PARENTS.has(parent)) {
        if (!text.trim()) continue;
        out.push(`<p>${xml(text)}</p>`);
      } else out.push(xml(text));
      continue;
    }
    const closing = m[1] === "/";
    const tag = m[2].toLowerCase();
    const a = attrsOf(m[3] || "");
    const selfClose = m[4] === "/" || tag === "img" || tag === "br" || tag === "hr";

    if (closing) {
      // Pop to the matching element (tolerates stray tags).
      const idx = stack.map((f) => f.tag).lastIndexOf(tag);
      if (idx < 0) continue;
      while (stack.length > idx) {
        const f = stack.pop()!;
        if (f.tag === "figure" && pendingGraphic) { out.push(...pendingGraphic); pendingGraphic = null; }
        out.push(f.close);
      }
      continue;
    }
    if (tag === "br") { out.push(" "); continue; }
    if (tag === "hr") continue;
    if (tag === "img") {
      const g = `<graphic xlink:href="${xml(absUrl(cfg, a.src))}"/>`;
      if (inside("figure") && pendingGraphic) pendingGraphic.push(g);
      else if (BLOCK_PARENTS.has(jatsParent())) out.push(`<p><inline-graphic xlink:href="${xml(absUrl(cfg, a.src))}"/></p>`);
      else out.push(`<inline-graphic xlink:href="${xml(absUrl(cfg, a.src))}"/>`);
      continue;
    }
    if (selfClose) continue;

    const push = (open: string, close: string, jats = "") => { out.push(open); stack.push({ tag, close, jats }); };
    const atTop = !stack.length;
    switch (tag) {
      case "h2": case "h3":
        if (atTop) {
          const depth = tag === "h2" ? 1 : 2;
          closeSecs(depth);
          if (depth === 2 && !secs.length) { out.push(`<sec>`); secs.push(1); out.push("<title/>"); }
          out.push(`<sec${a.id ? ` id="${xml(idPrefix + "sec-" + a.id)}"` : ""}>`);
          secs.push(depth);
          push("<title>", "</title>", "title");
        } else push("<p><bold>", "</bold></p>", "p");
        break;
      case "h4": case "h5": case "h6":
        if (top()?.jats === "boxed-text") push("<caption><title>", "</title></caption>", "title");
        else push("<p><bold>", "</bold></p>", "p");
        break;
      case "p":
        if (BLOCK_PARENTS.has(jatsParent())) push("<p>", "</p>", "p");
        else push("", "", "");
        break;
      case "ul": push('<list list-type="bullet">', "</list>", "list"); break;
      case "ol": push('<list list-type="order">', "</list>", "list"); break;
      case "li": push("<list-item><p>", "</p></list-item>", "p"); break;
      case "strong": case "b": push("<bold>", "</bold>"); break;
      case "em": case "i": push("<italic>", "</italic>"); break;
      case "u": push("<underline>", "</underline>"); break;
      case "sub": push("<sub>", "</sub>"); break;
      case "sup": push("<sup>", "</sup>"); break;
      case "aside": boxN++; push(`<boxed-text id="${idPrefix}box${boxN}">`, "</boxed-text>", "boxed-text"); break;
      case "figure":
        if (/\btbl\b/.test(a.class || "")) { tabN++; push(`<table-wrap id="${idPrefix}t${tabN}">`, "</table-wrap>", "table-wrap"); }
        else { figN++; pendingGraphic = []; push(`<fig id="${idPrefix}f${figN}">`, "</fig>", "fig"); }
        break;
      case "figcaption": push("<caption><p>", "</p></caption>", "p"); break;
      case "div":
        if (/\btable-wrap\b/.test(a.class || "") && !inside("figure")) { tabN++; push(`<table-wrap id="${idPrefix}t${tabN}">`, "</table-wrap>", "table-wrap"); }
        else push("", "");
        break;
      case "table": push("<table>", "</table>", "table"); break;
      case "thead": push("<thead>", "</thead>", "thead"); break;
      case "tbody": push("<tbody>", "</tbody>", "tbody"); break;
      case "tr": push("<tr>", "</tr>", "tr"); break;
      case "td": case "th": {
        const span = (a.colspan ? ` colspan="${xml(a.colspan)}"` : "") + (a.rowspan ? ` rowspan="${xml(a.rowspan)}"` : "");
        push(`<${tag}${span}>`, `</${tag}>`, "p");
        break;
      }
      case "a": {
        const href = a.href || "";
        const ref = href.match(/^#ref-(\d+)$/);
        if (ref) push(`<xref ref-type="bibr" rid="${idPrefix}ref-${ref[1]}">`, "</xref>");
        else if (/^(https?:|mailto:)/.test(href) && !inside("figure")) push(`<ext-link ext-link-type="uri" xlink:href="${xml(href)}">`, "</ext-link>");
        else push("", "");
        break;
      }
      default: push("", "");
    }
  }
  while (stack.length) out.push(stack.pop()!.close);
  closeSecs(1);
  return out.join("");
}

function refXml(ref: string, i: number) {
  const doi = doiIn(ref), pmid = pmidIn(ref);
  const ids = (doi ? ` <pub-id pub-id-type="doi">${xml(doi)}</pub-id>` : "") + (pmid ? ` <pub-id pub-id-type="pmid">${xml(pmid)}</pub-id>` : "");
  const text = plain(ref.replace(/<[^>]+>/g, ""));
  return `<ref id="ref-${i + 1}"><label>${i + 1}</label><mixed-citation>${xml(text)}${ids}</mixed-citation></ref>`;
}

export function jatsFront(a: Article, issue: Issue | null, cfg: JournalConfig) {
  const lic = licenceInfo(cfg);
  const authors = authorRecords(a);
  const affKeys = [...new Set(a.affiliations.map((x) => x.key.trim()))];
  const affId = (k: string) => `aff-${(k || String(affKeys.indexOf(k) + 1)).replace(/[^\w-]/g, "")}`;
  const m = monthNum(issue?.month);
  const L: string[] = [];
  L.push("<front>", "<journal-meta>");
  L.push(`<journal-id journal-id-type="publisher-id">KSP</journal-id>`);
  L.push(`<journal-id journal-id-type="nlm-ta">${xml(cfg.abbrevTitle)}</journal-id>`);
  L.push(`<journal-title-group><journal-title>${xml(cfg.title)}</journal-title><abbrev-journal-title abbrev-type="publisher">${xml(cfg.abbrevTitle)}</abbrev-journal-title></journal-title-group>`);
  if (cfg.issnPrint) L.push(`<issn publication-format="print">${xml(cfg.issnPrint)}</issn>`);
  if (cfg.issnOnline) L.push(`<issn publication-format="electronic">${xml(cfg.issnOnline)}</issn>`);
  L.push(`<publisher><publisher-name>${xml(cfg.publisher)}</publisher-name><publisher-loc>${xml(cfg.publisherAddress)}</publisher-loc></publisher>`);
  L.push("</journal-meta>", "<article-meta>");
  L.push(`<article-id pub-id-type="publisher-id">${xml(a.slug)}</article-id>`);
  if (a.doi) L.push(`<article-id pub-id-type="doi">${xml(a.doi)}</article-id>`);
  L.push(`<article-categories><subj-group subj-group-type="heading"><subject>${xml(a.articleType)}</subject></subj-group></article-categories>`);
  L.push(`<title-group><article-title>${xml(a.title)}</article-title></title-group>`);
  if (authors.length) {
    L.push('<contrib-group content-type="author">');
    authors.forEach((au) => {
      L.push(`<contrib contrib-type="author"${au.corresponding ? ' corresp="yes"' : ""}>`);
      L.push(`<name name-style="western"><surname>${xml(au.surname)}</surname>${au.given ? `<given-names>${xml(au.given)}</given-names>` : ""}</name>`);
      for (const k of au.affKeys) if (affKeys.includes(k)) L.push(`<xref ref-type="aff" rid="${affId(k)}"><sup>${xml(k)}</sup></xref>`);
      if (au.corresponding) L.push(`<xref ref-type="corresp" rid="cor1">*</xref>`);
      L.push("</contrib>");
    });
    L.push("</contrib-group>");
  }
  a.affiliations.forEach((af) => L.push(`<aff id="${affId(af.key.trim())}"><label>${xml(af.key)}</label>${xml(af.text)}</aff>`));
  if (a.correspondingAuthor || a.correspondingEmail) {
    L.push(`<author-notes><corresp id="cor1">Corresponding author: ${xml(a.correspondingAuthor || "")}${a.correspondingEmail ? ` <email>${xml(a.correspondingEmail)}</email>` : ""}</corresp></author-notes>`);
  }
  if (issue) {
    L.push(`<pub-date publication-format="print" date-type="pub" iso-8601-date="${issue.year}${m ? "-" + String(m).padStart(2, "0") : ""}">${m ? `<month>${m}</month>` : ""}<year>${issue.year}</year></pub-date>`);
    L.push(`<volume>${issue.volume}</volume><issue>${issue.number}</issue>`);
  }
  if (a.pageStart) L.push(`<fpage>${xml(a.pageStart)}</fpage>`);
  if (a.pageEnd) L.push(`<lpage>${xml(a.pageEnd)}</lpage>`);
  L.push(`<permissions><copyright-statement>© ${issue?.year ?? ""} ${xml(cfg.copyrightHolder)}</copyright-statement>${issue ? `<copyright-year>${issue.year}</copyright-year>` : ""}<copyright-holder>${xml(cfg.copyrightHolder)}</copyright-holder>`
    + `<license license-type="open-access" xlink:href="${xml(lic.url)}"><ali:license_ref>${xml(lic.url)}</ali:license_ref><license-p>This is an open access article distributed under the terms of the ${xml(lic.label)} licence.</license-p></license></permissions>`);
  L.push(`<self-uri xlink:href="${xml(articleUrl(cfg, a))}" content-type="html"/>`);
  const pdf = pdfUrl(cfg, a, issue);
  if (pdf) L.push(`<self-uri xlink:href="${xml(pdf)}" content-type="pdf"/>`);
  if (a.abstract.length) {
    L.push("<abstract>");
    let inSecs = false;
    for (const s of a.abstract) {
      const ps = plain(s.text).split(/\n+/).filter(Boolean).map((t) => `<p>${xml(t)}</p>`).join("");
      if (s.heading) inSecs = true;
      // Paragraphs can't follow a <sec>, so a heading-less part after a headed one becomes an untitled <sec>.
      L.push(s.heading ? `<sec><title>${xml(s.heading)}</title>${ps}</sec>` : inSecs ? `<sec><title/>${ps}</sec>` : ps);
    }
    L.push("</abstract>");
  }
  if (a.keywords.length) L.push(`<kwd-group kwd-group-type="author">${a.keywords.map((k) => `<kwd>${xml(k)}</kwd>`).join("")}</kwd-group>`);
  L.push("</article-meta>", "</front>");
  return L.join("\n");
}

export function jatsBack(a: Article, cfg: JournalConfig) {
  const parts: string[] = [];
  if (a.notesHtml) parts.push(`<notes notes-type="declarations"><title>Declarations</title>${htmlToJats(a.notesHtml, cfg, "n-")}</notes>`);
  if (a.refs.length) parts.push(`<ref-list><title>References</title>\n${a.refs.map(refXml).join("\n")}\n</ref-list>`);
  return parts.length ? `<back>\n${parts.join("\n")}\n</back>` : "";
}

/** The complete JATS document. `doctype` false for embedding (OAI-PMH). */
export function jatsArticle(a: Article, issue: Issue | null, cfg: JournalConfig, { doctype = true, body = true } = {}) {
  const head = doctype
    ? `<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE article PUBLIC "-//NLM//DTD JATS (Z39.96) Journal Publishing DTD v1.3 20210610//EN" "https://jats.nlm.nih.gov/publishing/1.3/JATS-journalpublishing1-3.dtd">\n`
    : "";
  const ns = 'xmlns:xlink="http://www.w3.org/1999/xlink" xmlns:mml="http://www.w3.org/1998/Math/MathML" xmlns:ali="http://www.niso.org/schemas/ali/1.0/"';
  const bodyXml = body && a.bodyHtml ? `<body>\n${htmlToJats(a.bodyHtml, cfg)}\n</body>` : "";
  return `${head}<article ${doctype ? "" : 'xmlns="https://jats.nlm.nih.gov/publishing/1.3/" '}${ns} article-type="${jatsType(a.articleType)}" dtd-version="1.3" xml:lang="${xml(cfg.language)}">\n${jatsFront(a, issue, cfg)}\n${bodyXml}\n${jatsBack(a, cfg)}\n</article>\n`;
}
